PATCHES = [('phone/server.py', 'сервер может слушать внешнюю сеть (нужно в облаке)', 'def start(port: int = None) -> int:\n    """Запустить сервер (только на этом компьютере; наружу его выводит туннель). → порт."""', 'def start(port: int = None, host: str = "127.0.0.1") -> int:\n    """Запустить сервер. На компьютере — только для него самого (наружу выводит туннель);\n    в облаке — host="0.0.0.0". → порт."""'), ('phone/server.py', 'сервер: адрес прослушивания из параметра', '    srv = make_server("127.0.0.1", PORT if port is None else port, app, server_class=_Server, handler_class=_Quiet)', '    srv = make_server(host, PORT if port is None else port, app, server_class=_Server, handler_class=_Quiet)'), ('phone/install.py', '«установи себя на телефон» — адрес облака, если он настроен', '    url = server.connect()\n    if not url:', '    cloud = (os.getenv("ATLAS_CLOUD_URL") or "").strip().rstrip("/")\n    url = cloud or server.connect()\n    if cloud:\n        server._state["kind"] = "cloud"\n    if not url:'), ('phone/install.py', 'страница QR: пометка «из облака»', '    note = {"tailscale": "Телефон должен быть в твоей сети Tailscale: приложение Tailscale установлено и включено.",', '    note = {"tailscale": "Телефон должен быть в твоей сети Tailscale: приложение Tailscale установлено и включено.",\n            "cloud": "Atlas отвечает из облака — компьютер для разговора не нужен. Музыка и программы — когда он включён.",')]
NEW = {'cloud/__init__.py': '"""\nAtlas в облаке (Hugging Face Spaces): тот же мозг, что на компьютере, без того, что умеет только Windows.\n\n    stubs.py             — модули «только для компьютера» → вежливые заглушки «недоступно из облака»\n    voice_cloud.py       — распознавание (Groq Whisper) и голос (Fish или Edge) без микрофона и колонок\n    file_search_cloud.py — только «векторы смысла» той же моделью, что на компьютере (память совпадает)\n    atlas_cloud.py       — запуск: память из Supabase → мозг → сервер для телефона на порту 7860\n    space/               — два файла для Hugging Face (Dockerfile, README.md)\n"""\n', 'cloud/stubs.py': '"""\nМодули, которые умеют работать только на компьютере, — в облаке заменяются заглушками.\n\nЗаглушка — это модуль, у которого есть ЛЮБАЯ функция: вызов возвращает «недоступно из облака».\nСлово «недоступ» мозг считает неудачей, поэтому не скажет «готово» за то, чего не сделал.\n\nimport_with_autostub() — запасная сетка: если какой-то модуль проекта не загрузился в облаке\n(нет Windows, нет библиотеки), он тоже подменяется заглушкой, а запуск продолжается.\n"""\nimport importlib\nimport os\nimport sys\nimport traceback\nimport types\n\nUNAVAILABLE = ("Это недоступно из облака: компьютер сейчас не на связи, а Atlas отвечает с сервера. "\n               "Скажи об этом коротко и предложи, что можно сделать отсюда.")\n\n# Только для компьютера: окна, файлы, звук, браузер, программы, железо\nPC_ONLY = (\n    "system_control", "file_control", "system_info", "reminders", "email_reader", "theme_control",\n    "system_advanced", "media_control", "dev_tools", "listening_mode", "calendar_control", "network_utils",\n    "text_utils", "browser_agent", "deep_links", "web_gui", "window_hotkey", "hotkeys", "selection_hotkey",\n    "core.desktop_agent", "core.holo", "core.gestures", "core.day_report", "core.healer", "core.skill_forge",\n    "core.missions", "core.proactive", "core.speaker_id", "core.bus",\n)\n\n\ndef _unavailable(name: str):\n    def f(*args, **kwargs):\n        return UNAVAILABLE\n    f.__name__ = name\n    f.__doc__ = "Недоступно из облака."\n    return f\n\n\nclass _StubModule(types.ModuleType):\n    """Любой атрибут — функция «недоступно из облака». Константы и классы, если их спросят, — тоже вызываемые."""\n\n    def __getattr__(self, name):\n        if name.startswith("__"):\n            raise AttributeError(name)\n        f = _unavailable(name)\n        setattr(self, name, f)\n        return f\n\n\ndef stub(name: str, **attrs) -> types.ModuleType:\n    m = _StubModule(name)\n    m.__dict__.update(attrs)\n    m.__atlas_stub__ = True\n    m.__path__ = []                                   # чтобы «from x.y import z» тоже работало\n    sys.modules[name] = m\n    parent, _, child = name.rpartition(".")\n    if parent and parent in sys.modules:\n        setattr(sys.modules[parent], child, m)\n    return m\n\n\ndef install_pc_stubs(extra=()) -> list:\n    done = []\n    for name in tuple(PC_ONLY) + tuple(extra):\n        stub(name)\n        done.append(name)\n    return done\n\n\ndef _project_module_of(exc: BaseException):\n    """Какой модуль проекта упал при загрузке (последний файл проекта в трассировке)."""\n    root = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))\n    for frame in reversed(traceback.extract_tb(exc.__traceback__)):\n        path = os.path.abspath(frame.filename)\n        if path.startswith(root) and "/cloud/" not in path.replace("\\\\", "/") and path.endswith(".py"):\n            rel = os.path.relpath(path, root)[:-3].replace(os.sep, ".")\n            return rel[:-9] if rel.endswith(".__init__") else rel\n    return None\n\n\ndef import_with_autostub(name: str, keep=(), limit: int = 40):\n    """Импортировать модуль; если по дороге что-то не загрузилось — подменить это заглушкой и повторить.\n    keep — модули, которые подменять нельзя (без них облако бессмысленно): тогда ошибка поднимается."""\n    stubbed = []\n    for _ in range(limit):\n        try:\n            return importlib.import_module(name), stubbed\n        except ModuleNotFoundError as e:\n            missing = e.name or ""\n            if not missing or missing in keep or missing == name:\n                raise\n            stub(missing)\n            stubbed.append(missing)\n        except Exception as e:\n            bad = _project_module_of(e)\n            if not bad or bad in keep or bad == name or bad in stubbed:\n                raise\n            for k in [k for k in sys.modules if k == bad or k.startswith(bad + ".")]:\n                del sys.modules[k]\n            stub(bad)\n            stubbed.append(bad)\n        for k in [k for k in list(sys.modules) if k == name]:\n            del sys.modules[k]\n    raise RuntimeError(f"не удалось загрузить {name}: слишком много заглушек ({stubbed})")\n', 'cloud/voice_cloud.py': '"""\nvoice для облака: без микрофона и колонок — только то, что нужно телефону.\n\n    распознавание: Groq Whisper (как на компьютере, те же настройки языка)\n    голос:         Fish Audio, если заданы FISH_API_KEY и FISH_VOICE_RU / FISH_VOICE_EN,\n                   иначе бесплатный Edge (Дмитрий — русский, Ryan — английский)\nГолоса и устройства компьютера отсюда не переключаются.\n"""\nimport asyncio\nimport os\nimport re\nimport threading\n\nfrom cloud.stubs import UNAVAILABLE\n\ntry:\n    from groq import Groq\n    groq_client = Groq(api_key=os.getenv("GROQ_API_KEY"))\nexcept Exception as _e:                              # без ключа облако всё равно запустится — скажет при запросе\n    print(f"[облако] Groq для распознавания недоступен: {_e}")\n    groq_client = None\n\nSTT_WHISPER = os.getenv("STT_MODEL") or "whisper-large-v3"\n_STT_BASE_PROMPT = ("Это обычный разговор с голосовым ассистентом Атлас: вопросы и просьбы на русском языке, "\n                    "иногда с английскими словами. Бишкек.")\n_WHISPER_JUNK = {"продолжение следует", "субтитры сделал dimatorzok", "спасибо за просмотр", "thanks for watching",\n                 "thank you for watching", "subtitles by the amara.org community"}\n_response_language = {"lang": (os.getenv("ATLAS_LANG") or "ru").lower()[:2]}\n_stop_speaking = threading.Event()\nEDGE_VOICES = {"ru": os.getenv("EDGE_VOICE_RU") or "ru-RU-DmitryNeural",\n               "en": os.getenv("EDGE_VOICE_EN") or "en-GB-RyanNeural"}\n\n\ndef get_response_language() -> str:\n    return _response_language["lang"]\n\n\ndef set_response_language(lang: str) -> str:\n    lang = (lang or "").lower().strip()\n    if lang not in ("en", "ru", "english", "russian"):\n        return "Supported languages: English or Russian."\n    _response_language["lang"] = "ru" if lang.startswith("ru") else "en"\n    return f"Language switched to {\'Russian\' if _response_language[\'lang\'] == \'ru\' else \'English\'}."\n\n\ndef _stt_prompt() -> str:\n    extra = (os.getenv("STT_VOCAB") or "").strip()\n    return (_STT_BASE_PROMPT + (" " + extra if extra else ""))[:600]\n\n\ndef _stt_language():\n    fixed = (os.getenv("STT_LANGUAGE") or "").strip().lower()\n    if fixed in ("ru", "en"):\n        return fixed\n    return "ru" if _response_language["lang"] == "ru" else None\n\n\ndef _lang_of(text: str) -> str:\n    return "ru" if re.search(r"[а-яё]", text or "", re.I) else _response_language["lang"]\n\n\ndef _fish(text: str, filename: str, voice_id: str) -> None:\n    import httpx\n    from core import emotions\n    fmt = "mp3" if filename.endswith(".mp3") else "wav"\n    model = os.getenv("FISH_MODEL", "s2.1-pro-free")\n    r = httpx.post("https://api.fish.audio/v1/tts", timeout=60,\n                   headers={"Authorization": f"Bearer {os.getenv(\'FISH_API_KEY\')}", "Content-Type": "application/json",\n                            "model": model},\n                   json={"text": emotions.for_fish(text, model), "reference_id": voice_id, "format": fmt})\n    if r.status_code != 200:\n        raise RuntimeError(f"Fish {r.status_code}: {r.text[:200]}")\n    with open(filename, "wb") as f:\n        f.write(r.content)\n\n\ndef _edge(text: str, filename: str, lang: str) -> None:\n    import edge_tts\n    from core import emotions\n\n    async def gen():\n        await edge_tts.Communicate(emotions.strip(text), EDGE_VOICES[lang]).save(filename)\n    asyncio.run(gen())\n\n\ndef _generate_any(text: str, filename: str) -> str:\n    """Голос ответа в файл (mp3). Fish — если настроен, иначе Edge. → путь к файлу."""\n    lang = _lang_of(text)\n    voice_id = os.getenv("FISH_VOICE_RU" if lang == "ru" else "FISH_VOICE_EN")\n    if voice_id and os.getenv("FISH_API_KEY"):\n        try:\n            _fish(text, filename, voice_id)\n            return filename\n        except Exception as e:\n            print(f"[облако] Fish не ответил ({e}) — говорю голосом Edge")\n    _edge(text, filename, lang)\n    return filename\n\n\n# голоса и устройства компьютера отсюда не переключаются\ndef _pc_only(*a, **k):\n    return UNAVAILABLE\n\n\nlist_voices = set_voice = list_audio_devices = set_microphone = set_speaker = _pc_only\nlist_elevenlabs_voices = set_elevenlabs_voice = _pc_only\n\n\ndef output_is_headphones() -> bool:\n    return True\n', 'cloud/file_search_cloud.py': '"""\nfile_search для облака: только «векторы смысла» — ТОЙ ЖЕ моделью и тем же способом, что на компьютере,\nиначе память из Supabase (её векторы посчитаны компьютером) не совпадёт с вопросами.\nПоиск файлов на диске и их открытие — недоступны из облака.\n"""\nimport os\nimport threading\n\nimport numpy as np\n\nfrom cloud.stubs import UNAVAILABLE\n\nEMB_MODEL = "sentence-transformers/paraphrase-multilingual-MiniLM-L12-v2"     # как в file_search.py компьютера\nMODEL_CACHE = os.path.join(os.path.expanduser("~"), ".cache", "atlas_models")\n_embedder = None\n_emb_lock = threading.Lock()\n_ORD = {"первый": 1, "второй": 2, "третий": 3, "first": 1, "second": 2, "third": 3}\n\n\ndef _embed(texts: list) -> np.ndarray:\n    global _embedder\n    with _emb_lock:\n        if _embedder is None:\n            from fastembed import TextEmbedding\n            print("[облако] загружаю модель векторов смысла (та же, что на компьютере)...")\n            _embedder = TextEmbedding(EMB_MODEL, cache_dir=MODEL_CACHE)\n        vecs = np.array(list(_embedder.embed(texts, batch_size=32)), dtype=np.float32)\n    norms = np.linalg.norm(vecs, axis=1, keepdims=True)\n    return vecs / np.maximum(norms, 1e-9)\n\n\ndef search_file_content(query: str = "", max_results: int = 5) -> str:\n    return UNAVAILABLE\n\n\ndef open_found_file(query: str = "") -> str:\n    return UNAVAILABLE\n\n\ndef open_search_result(n=1) -> str:\n    return UNAVAILABLE\n\n\ndef show_search_result_in_folder(n=1) -> str:\n    return UNAVAILABLE\n\n\nfor _f in (search_file_content, open_found_file, open_search_result, show_search_result_in_folder):\n    _f.__doc__ = "Недоступно из облака."                 # мозг уберёт их из того, что видит модель\n\n\ndef build_index_background() -> None:\n    pass\n\n\ndef index_status() -> str:\n    return "Индекс файлов есть только на компьютере."\n', 'cloud/ui_state_cloud.py': '"""ui_state для облака: окна интерфейса нет — состояние живёт в памяти процесса."""\nshared_state = {"chat_history": [], "manual_queue": [], "state": "idle", "text": ""}\n\n\ndef notify(*args, **kwargs):\n    pass\n', 'cloud/atlas_cloud.py': '"""\nAtlas в облаке — запуск.\n\n    1. модули «только для компьютера» → заглушки «недоступно из облака»\n    2. память: всё из Supabase (тот же граф, разговоры, карточки, заметки), дальше синхронизация\n    3. мозг — тот же код, что на компьютере\n    4. сервер для телефона на порту 7860 (Hugging Face) с тем же ключом сопряжения\n\nСекреты Space (Settings → Variables and secrets): GROQ_API_KEY, CEREBRAS_API_KEY, GEMINI_API_KEY (по желанию),\nSUPABASE_URL, SUPABASE_SERVICE_KEY, PHONE_KEY, FISH_API_KEY + FISH_VOICE_RU / FISH_VOICE_EN (по желанию).\n\n    python -m cloud.atlas_cloud\n"""\nimport os\nimport sys\nimport threading\nimport time\n\nROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))\nif ROOT not in sys.path:\n    sys.path.insert(0, ROOT)\n\nfrom cloud import stubs  # noqa: E402\n\nCLOUD_HINT = ("(Said on the phone; Atlas is answering from the cloud server and the computer is not available: "\n              "reply in 1-2 short spoken sentences; for anything that needs the computer — music, apps, files, "\n              "volume — say briefly that it works when the computer is on.) ")\n# без этого облако бессмысленно — если не загрузились, лучше честно упасть с ошибкой в логе Space\nESSENTIAL = ("ai_brain", "brain", "brain.state", "brain.prompt", "brain.providers", "brain.tools", "brain.features",\n             "brain.planner", "brain.instant", "brain.pipeline", "tool_router", "core", "core.llm_gateway",\n             "core.memory", "core.cloud_sync", "phone", "phone.server", "openai")\n_state = {"stubbed": [], "memory": None}\n\n# Функции, которые мозг использует как проверку или список: у заглушки они должны отвечать\n# «пусто» / «нет», а не фразой «недоступно» (иначе, например, «идёт игра» станет всегда «да»).\nSAFE_DEFAULTS = {\n    "core.skills": {"load_skills": lambda: {}},\n    "skills.fun": {"game_active": lambda: False},\n    "core.study": {"active": lambda: False},\n    "core.routines": {"match_trigger": lambda q: None, "log_tools": lambda *a: None},\n    "core.skill_forge": {"installed": lambda: [], "list_items": lambda n=10: [], "load_skill": lambda name: None,\n                         "start": lambda *a, **k: None},\n}\n\n\ndef _is_unavailable(fn) -> bool:\n    while fn is not None:\n        if getattr(fn, "__doc__", "") == "Недоступно из облака.":\n            return True\n        fn = getattr(fn, "__wrapped__", None)\n    return False\n\n\n# Обёртки мозга над компьютерными модулями (голо-экран, жесты, мастерская навыков, самолечение,\n# мини-окно, ритуалы с действиями на компьютере, установка на устройства) — по метке их не распознать\nCLOUD_HIDE = {"holo_show", "holo_weather", "holo_graph", "holo_control", "look", "gestures_control", "learn_skill",\n              "install_skill", "reject_skill", "list_learned_skills", "remove_skill", "heal_status", "heal_apply",\n              "heal_reject", "day_report", "mini_mode", "install_on_device", "create_routine", "list_routines",\n              "run_routine", "delete_routine", "get_cpu_usage"}   # нагрузка сервера — не твоего компьютера\n\n\ndef _hide_pc_tools() -> list:\n    """Инструменты «только для компьютера» убрать из того, что видит модель: иначе она выберет их,\n    получит «недоступно» и потратит шаг. Быстрый путь по-прежнему ответит «недоступно» сам."""\n    from brain import tools\n    hidden = sorted(n for n, f in tools.AVAILABLE_FUNCTIONS.items() if _is_unavailable(f) or n in CLOUD_HIDE)\n    tools.TOOLS_SCHEMA[:] = [t for t in tools.TOOLS_SCHEMA if t["function"]["name"] not in hidden]\n    try:\n        import tool_router\n        tool_router._tool_index["mat"] = None          # смысловой индекс пересоберётся без них\n    except Exception:\n        pass\n    return hidden\n\n\ndef _prepare_optional() -> list:\n    """Необязательные модули — загрузить заранее; если стали заглушкой — безопасные ответы."""\n    got = []\n    for name, attrs in SAFE_DEFAULTS.items():\n        try:\n            mod, more = stubs.import_with_autostub(name, keep=ESSENTIAL)\n            got += more\n        except Exception as e:\n            print(f"[облако] {name}: {e} — заменяю заглушкой")\n            mod = stubs.stub(name)\n            got.append(name)\n        if getattr(mod, "__atlas_stub__", False):\n            for k, v in attrs.items():\n                setattr(mod, k, v)\n    return got\n\n\ndef _replace(name: str, module) -> None:\n    sys.modules[name] = module\n\n\ndef boot(serve: bool = True, port: int = None):\n    """Поднять облачного Atlas. serve=False — без сервера (для тестов). → модуль сервера телефона."""\n    t0 = time.time()\n    stubs.install_pc_stubs()\n    import cloud.voice_cloud as voice_cloud\n    import cloud.file_search_cloud as fs_cloud\n    import cloud.ui_state_cloud as ui_cloud\n    for name, mod in (("voice", voice_cloud), ("file_search", fs_cloud), ("ui_state", ui_cloud)):\n        if not getattr(sys.modules.get(name), "__atlas_test__", False):   # тесты могут дать свои\n            _replace(name, mod)\n\n    from core import cloud_sync\n    store = cloud_sync.store_from_env()\n    if store is not None:\n        try:\n            r = cloud_sync.sync_once(store)\n            _state["memory"] = r\n            print(f"[облако] память из Supabase: получено {r[\'pulled\']} записей")\n        except Exception as e:\n            print(f"[облако] память из Supabase не загрузилась ({e}) — начну с пустой, попробую ещё раз")\n    else:\n        print("[облако] нет SUPABASE_URL / SUPABASE_SERVICE_KEY — память будет только своя, без компьютера")\n\n    # окна и буфера обмена в облаке нет — тихие пустые ответы вместо ошибок в журнале\n    stubs.stub("pygetwindow", getActiveWindow=lambda: None)\n    stubs.stub("pyperclip", paste=lambda: "", copy=lambda text: None)\n    stubs.stub("pyautogui", hotkey=lambda *a, **k: None, position=lambda: (0, 0))\n    early = _prepare_optional()\n    ai_brain, stubbed = stubs.import_with_autostub("ai_brain", keep=ESSENTIAL)\n    stubbed = early + stubbed\n    _, more = stubs.import_with_autostub("fast_commands", keep=ESSENTIAL)\n    _state["stubbed"] = sorted(set(stubbed + more))\n    if _state["stubbed"]:\n        print(f"[облако] дополнительно заменены заглушками: {\', \'.join(_state[\'stubbed\'])}")\n\n    hidden = _hide_pc_tools()\n    print(f"[облако] модели не показываются {len(hidden)} инструментов, которые работают только на компьютере")\n\n    from phone import server\n    key = (os.getenv("PHONE_KEY") or "").strip()\n    server.pairing_token = lambda create=False: key\n    server.PHONE_HINT = os.getenv("PHONE_HINT") or CLOUD_HINT\n    if not key:\n        print("[облако] нет PHONE_KEY — телефон не сможет подключиться (секрет в настройках Space)")\n    if store is not None:\n        cloud_sync.start()\n    print(f"[облако] Atlas готов за {time.time() - t0:.1f} с")\n    if serve:\n        server.start(port=port or int(os.getenv("PORT") or 7860), host="0.0.0.0")\n        threading.Event().wait()                      # сервер работает в своём потоке; держим процесс\n    return server\n\n\nif __name__ == "__main__":\n    for _stream in (sys.stdout, sys.stderr):\n        try:\n            _stream.reconfigure(encoding="utf-8", errors="replace", line_buffering=True)\n        except Exception:\n            pass\n    boot()\n', 'cloud/space_secrets.py': '"""\nЧто вписать в секреты Hugging Face Space — из твоего .env и ключа сопряжения телефона.\n\n    python -m cloud.space_secrets\n\nВыводит значения на ЭТОТ экран. Никому их не показывай и не присылай в чат.\n"""\nimport json\nimport os\nimport sys\n\nROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))\nREQUIRED = ("GROQ_API_KEY", "SUPABASE_URL", "SUPABASE_SERVICE_KEY", "PHONE_KEY")\nOPTIONAL = ("CEREBRAS_API_KEY", "GEMINI_API_KEY", "FISH_API_KEY", "FISH_VOICE_RU", "FISH_VOICE_EN", "STT_LANGUAGE")\n\n\ndef collect() -> dict:\n    try:\n        from dotenv import dotenv_values\n        env = dict(dotenv_values(os.path.join(ROOT, ".env")))\n    except Exception:\n        env = {}\n    env = {k: v for k, v in env.items() if v}\n    try:\n        with open(os.path.join(ROOT, "phone_pairing.json"), encoding="utf-8") as f:\n            env["PHONE_KEY"] = json.load(f).get("token", "")\n    except Exception:\n        pass\n    # голос Fish: первый русский/английский из FISH_VOICES_RU / FISH_VOICES_EN («Имя:id,…»)\n    for lang in ("RU", "EN"):\n        lst = env.get(f"FISH_VOICES_{lang}") or ""\n        first = next((x.split(":", 1)[1].strip() for x in lst.split(",") if ":" in x), "")\n        if first and not env.get(f"FISH_VOICE_{lang}"):\n            env[f"FISH_VOICE_{lang}"] = first\n    return env\n\n\ndef main():\n    for s in (sys.stdout, sys.stderr):\n        try:\n            s.reconfigure(encoding="utf-8", errors="replace")\n        except Exception:\n            pass\n    env = collect()\n    print("Hugging Face → твой Space → Settings → Variables and secrets → New secret.\\n"\n          "Имя — слева, значение — справа. Это ключи: никому не показывай.\\n")\n    missing = []\n    for name in REQUIRED:\n        if env.get(name):\n            print(f"  {name} = {env[name]}")\n        else:\n            missing.append(name)\n    print("\\nПо желанию (быстрее модели, голос Fish):")\n    for name in OPTIONAL:\n        if env.get(name):\n            print(f"  {name} = {env[name]}")\n    if missing:\n        print(f"\\n✗ Не хватает: {\', \'.join(missing)}"\n              + (" — PHONE_KEY появится после «Атлас, установи себя на телефон»." if "PHONE_KEY" in missing else ""))\n\n\nif __name__ == "__main__":\n    main()\n', 'cloud/requirements.txt': '# Atlas в облаке (Hugging Face Space). Только то, что нужно без Windows.\nopenai\ngroq\nnumpy\nfastembed\npython-dotenv\nhttpx\nedge-tts\nsqlalchemy\npillow\nsnowballstemmer\nrequests\n', 'cloud/space/Dockerfile': '# Atlas в облаке. Код берётся из GitHub при сборке — чтобы обновить облако после git push:\n# Space → Settings → Factory rebuild.\nFROM python:3.12-slim\n\nRUN apt-get update && apt-get install -y --no-install-recommends git ca-certificates \\\n    && rm -rf /var/lib/apt/lists/*\n\n# Hugging Face запускает контейнер от пользователя с id 1000\nRUN useradd -m -u 1000 user\nUSER user\nENV HOME=/home/user PATH=/home/user/.local/bin:$PATH PYTHONUNBUFFERED=1 PYTHONIOENCODING=utf-8\nWORKDIR /home/user\n\nARG ATLAS_REPO=https://github.com/alimtszyu13-svg/atlas-personal-assistant.git\nRUN git clone --depth 1 "$ATLAS_REPO" app\nWORKDIR /home/user/app\nRUN pip install --no-cache-dir --user -r cloud/requirements.txt\n\nEXPOSE 7860\nCMD ["python", "-m", "cloud.atlas_cloud"]\n', 'cloud/space/README.md': '---\ntitle: Atlas\nemoji: ⭐\ncolorFrom: indigo\ncolorTo: blue\nsdk: docker\napp_port: 7860\npinned: false\n---\n\nAtlas — голосовой ассистент. Это его облачная часть: телефон говорит с ней, когда компьютер выключен.\nКод: https://github.com/alimtszyu13-svg/atlas-personal-assistant\n', '.github/workflows/keepalive.yml': '# Бесплатный Space засыпает после 48 часов без запросов — раз в день «будим» облачного Atlas.\n# Адрес Space: GitHub → Settings → Secrets and variables → Actions → Variables → ATLAS_CLOUD_URL.\nname: keep cloud Atlas awake\n\non:\n  schedule:\n    - cron: "17 3 * * *"\n  workflow_dispatch:\n\njobs:\n  ping:\n    runs-on: ubuntu-latest\n    if: ${{ vars.ATLAS_CLOUD_URL != \'\' }}\n    steps:\n      - run: curl -fsS --max-time 120 "${{ vars.ATLAS_CLOUD_URL }}/" -o /dev/null && echo "Atlas в облаке на связи"\n', 'tests/test_cloud_brain.py': '"""\nТесты Atlas в облаке (cloud/).\n\n    python tests/test_cloud_brain.py\n\nЗагружается настоящий мозг, но память, заметки и журнал подменены (на компьютере ничего не меняется),\nмодель векторов не скачивается, модели и голос — подставные, интернет не нужен.\n"""\nimport base64\nimport hashlib\nimport io\nimport json\nimport os\nimport re\nimport sys\nimport tempfile\nimport traceback\nimport types\nfrom wsgiref.util import setup_testing_defaults\n\nfor _stream in (sys.stdout, sys.stderr):\n    try:\n        _stream.reconfigure(encoding="utf-8", errors="replace")\n    except Exception:\n        pass\n\nROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))\nsys.path.insert(0, ROOT)\nos.environ.update(GROQ_API_KEY="test", PHONE_KEY="k123", ATLAS_LANG="ru")\nfor k in ("CEREBRAS_API_KEY", "GEMINI_API_KEY", "GITHUB_MODELS_TOKEN", "SUPABASE_URL", "SUPABASE_SERVICE_KEY",\n          "FISH_API_KEY", "ATLAS_CLOUD_URL", "PHONE_HINT"):\n    os.environ.pop(k, None)\nLOG = {"asked": [], "tts": [], "opened": []}\n\n\ndef _mod(name, **attrs):\n    m = types.ModuleType(name)\n    m.__dict__.update(attrs)\n    m.__atlas_test__ = True\n    sys.modules[name] = m\n    return m\n\n\ndef isolate():\n    """Память, уроки, ритуалы и журнал — подставные: тест ничего не пишет в данные на компьютере."""\n    import importlib\n    core = importlib.import_module("core") if os.path.isdir(os.path.join(ROOT, "core")) else _mod("core")\n    for name, attrs in (\n        ("core.memory", dict(log_turn=lambda *a: None, recall_block=lambda q: None, upsert_fact=lambda *a, **k: None,\n                             start_sleep_cycle=lambda: None, _graph={"dirty": True}, _cache={"dirty": True})),\n        ("core.lessons", dict(lessons_block=lambda q: "", is_correction=lambda q: False, record_turn=lambda *a: None,\n                              learn_from_correction=lambda *a: None, learned_tools=lambda q: [])),\n        ("core.routines", dict(match_trigger=lambda q: None, log_tools=lambda *a: None, run=lambda r: "")),\n    ):\n        m = _mod(name, **attrs)\n        setattr(core, name.split(".")[1], m)\n    _mod("database", log_task=lambda *a: None, save_memory=lambda *a, **k: "ok", recall_memories=lambda *a, **k: "",\n         forget_memory=lambda *a, **k: "")\n    for lib, attrs in (("openai", None), ("groq", None), ("dotenv", None), ("edge_tts", None)):\n        try:\n            importlib.import_module(lib)\n        except ImportError:                                  # в песочнице без библиотек\n            if lib == "openai":\n                class OpenAI:\n                    def __init__(self, **kw):\n                        self.chat = types.SimpleNamespace(completions=types.SimpleNamespace(create=None))\n                        self.models = types.SimpleNamespace(list=lambda: types.SimpleNamespace(data=[]))\n                _mod("openai", OpenAI=OpenAI)\n            elif lib == "groq":\n                _mod("groq", Groq=lambda **k: types.SimpleNamespace())\n            elif lib == "dotenv":\n                _mod("dotenv", load_dotenv=lambda *a, **k: None, dotenv_values=lambda p: {})\n            else:\n                _mod("edge_tts", Communicate=None)\n    try:\n        importlib.import_module("core.llm_gateway")\n    except ImportError:                                      # песочница: шлюз из тестовых заглушек мозга\n        gw = _mod("core.llm_gateway", MODEL_TPM={}, MODEL_PENALTY={})\n        gw.fit = lambda msgs, schema, limit=0: msgs\n        gw.estimate = lambda x: 100\n        gw.plan = lambda c, e: (c[0], 0, 8000)\n        gw.reserve_any = lambda c, e, chk=None: c[0]\n        gw.record = lambda *a, **k: None\n        gw.chars = lambda x: 100\n        gw.cooldown = lambda *a: None\n        gw.busy = lambda m: False\n        core.llm_gateway = gw\n\n\ndef fake_embed(texts):\n    import numpy as np\n    out = []\n    for t in texts:\n        v = np.zeros(64, dtype=np.float32)\n        for w in str(t).lower().split():\n            v[int(hashlib.md5(w.encode()).hexdigest(), 16) % 64] += 1\n        out.append(v / (np.linalg.norm(v) or 1))\n    return np.array(out)\n\n\ndef call(path, method="GET", body=b"", headers=None):\n    env = {"REQUEST_METHOD": method, "PATH_INFO": path, "wsgi.input": io.BytesIO(body),\n           "CONTENT_LENGTH": str(len(body))}\n    for k, v in (headers or {}).items():\n        env["CONTENT_TYPE" if k.lower() == "content-type" else "HTTP_" + k.upper().replace("-", "_")] = v\n    setup_testing_defaults(env)\n    got = {}\n\n    def start_response(status, hdrs):\n        got["status"] = int(status.split()[0])\n    data = b"".join(S.app(env, start_response))\n    return got["status"], json.loads(data) if data[:1] in (b"{", b"[") else data\n\n\nTESTS = []\n\n\ndef test(fn):\n    TESTS.append(fn)\n    return fn\n\n\n@test\ndef pc_only_tools_say_unavailable_and_count_as_failure():\n    from brain import tools\n    from cloud.stubs import UNAVAILABLE\n    for name, args in (("open_app", {"app_name": "notepad"}), ("play_on_spotify", {"query": "lofi"}),\n                       ("volume_up", {}), ("search_file_content", {"query": "SAT"})):\n        if name not in tools.AVAILABLE_FUNCTIONS:\n            continue\n        res, ok, _ = tools._run_one_tool(name, args)\n        assert res == UNAVAILABLE and tools._TRACE_FAIL.search(str(res)), (name, res)\n\n\n@test\ndef model_never_sees_computer_only_tools():\n    from brain import tools\n    names = {t["function"]["name"] for t in tools.TOOLS_SCHEMA}\n    for pc in ("open_app", "play_on_spotify", "volume_up", "browser_open", "desktop_type", "search_file_content",\n               "holo_weather", "look", "learn_skill", "install_on_device", "run_routine"):\n        assert pc not in names, pc\n    assert {"execute_plan", "update_plan"} <= names, "мозговые инструменты на месте"\n\n\n@test\ndef phone_question_answered_from_the_cloud_with_voice():\n    from brain import providers\n\n    def model(on_text, **kw):\n        LOG["asked"].append(kw["messages"])\n        return {"role": "assistant", "content": "Солнечно, сэр."}, None\n    providers._call_model_stream = model\n    st, r = call("/api/ask", "POST", json.dumps({"text": "что посмотреть вечером?"}).encode(),\n                 {"Content-Type": "application/json", "X-Atlas-Key": "k123"})\n    assert st == 200 and r["text"] == "Солнечно, сэр." and base64.b64decode(r["audio"]) == b"EDGE-MP3", r\n    user_msgs = [m["content"] for m in LOG["asked"][0] if m.get("role") == "user"]\n    assert user_msgs[-1].startswith("(Respond in Russian.) (Said on the phone; Atlas is answering from the cloud"), \\\n        user_msgs[-1][:120]\n\n\n@test\ndef only_the_paired_phone_gets_in():\n    st, r = call("/api/ask", "POST", b\'{"text":"hi"}\', {"Content-Type": "application/json", "X-Atlas-Key": "wrong"})\n    assert st == 401\n    st, r = call("/")\n    assert st == 200 and b\'id="star"\' in r, "приложение отдаётся (без ключа оно ничего не умеет)"\n\n\n@test\ndef same_embedding_model_as_the_computer():\n    from cloud import file_search_cloud\n    pc = os.path.join(ROOT, "file_search.py")\n    if os.path.exists(pc):\n        m = re.search(r\'^EMB_MODEL\\s*=\\s*"([^"]+)"\', open(pc, encoding="utf-8").read(), re.M)\n        assert m and m.group(1) == file_search_cloud.EMB_MODEL, (m and m.group(1), file_search_cloud.EMB_MODEL)\n    assert file_search_cloud.EMB_MODEL == "sentence-transformers/paraphrase-multilingual-MiniLM-L12-v2"\n\n\n@test\ndef broken_module_is_replaced_not_fatal():\n    from cloud import stubs\n    d = tempfile.mkdtemp()\n    with open(os.path.join(d, "atlas_badmod.py"), "w", encoding="utf-8") as f:\n        f.write("import ctypes\\nctypes.windll.user32  # только Windows\\n")\n    with open(os.path.join(d, "atlas_uses_bad.py"), "w", encoding="utf-8") as f:\n        f.write("import atlas_badmod\\nVALUE = 42\\n")\n    sys.path.insert(0, d)\n    try:\n        saved = stubs._project_module_of\n        stubs._project_module_of = lambda e: "atlas_badmod"           # временная папка — не в проекте\n        mod, stubbed = stubs.import_with_autostub("atlas_uses_bad")\n        assert mod.VALUE == 42 and stubbed == ["atlas_badmod"], stubbed\n    finally:\n        stubs._project_module_of = saved\n        sys.path.remove(d)\n\n\n@test\ndef install_points_the_phone_to_the_cloud():\n    from phone import install as I\n    import webbrowser\n    os.environ["ATLAS_CLOUD_URL"] = "https://alim-atlas.hf.space/"\n    saved = webbrowser.open\n    webbrowser.open = lambda url: LOG["opened"].append(url)\n    try:\n        msg = I.install("телефон")\n        path = LOG["opened"][-1].replace("file:///", "/" if os.name != "nt" else "")\n        page = open(path, encoding="utf-8").read()\n        assert "QR" in msg and ("https://alim-atlas.hf.space/?pair=k123" in page or "<img" in page), msg\n        assert "из облака" in page\n    finally:\n        webbrowser.open = saved\n        os.environ.pop("ATLAS_CLOUD_URL", None)\n\n\n@test\ndef space_files_are_ready():\n    df = open(os.path.join(ROOT, "cloud", "space", "Dockerfile"), encoding="utf-8").read()\n    rd = open(os.path.join(ROOT, "cloud", "space", "README.md"), encoding="utf-8").read()\n    req = open(os.path.join(ROOT, "cloud", "requirements.txt"), encoding="utf-8").read()\n    assert \'CMD ["python", "-m", "cloud.atlas_cloud"]\' in df and "-u 1000" in df and "EXPOSE 7860" in df\n    assert "sdk: docker" in rd and "app_port: 7860" in rd\n    assert all(p in req for p in ("fastembed", "edge-tts", "openai", "groq"))\n\n\n@test\ndef secrets_helper_collects_what_to_paste():\n    from cloud import space_secrets\n    d = tempfile.mkdtemp()\n    with open(os.path.join(d, ".env"), "w", encoding="utf-8") as f:\n        f.write("GROQ_API_KEY=g1\\nSUPABASE_URL=https://x.supabase.co\\nSUPABASE_SERVICE_KEY=sb_secret_1\\n"\n                "FISH_API_KEY=f1\\nFISH_VOICES_RU=Володарский:abc123,Другой:zzz\\n")\n    with open(os.path.join(d, "phone_pairing.json"), "w", encoding="utf-8") as f:\n        json.dump({"token": "tok"}, f)\n    saved = space_secrets.ROOT\n    space_secrets.ROOT = d\n    try:\n        env = space_secrets.collect()\n    finally:\n        space_secrets.ROOT = saved\n    if env.get("GROQ_API_KEY"):                              # python-dotenv есть (на компьютере — всегда)\n        assert env["PHONE_KEY"] == "tok" and env["FISH_VOICE_RU"] == "abc123" and env["SUPABASE_URL"].endswith("supabase.co")\n\n\ndef main():\n    global S\n    isolate()\n    from cloud import atlas_cloud, file_search_cloud, voice_cloud\n    file_search_cloud._embed = fake_embed\n    voice_cloud._edge = lambda text, fn, lang: (LOG["tts"].append(text), open(fn, "wb").write(b"EDGE-MP3"))\n    S = atlas_cloud.boot(serve=False)\n    sys.modules["file_search"]._embed = fake_embed\n    ok = 0\n    for t in TESTS:\n        try:\n            t()\n            ok += 1\n            print(f"  ✓ {t.__name__}")\n        except Exception:\n            print(f"  ✗ {t.__name__}\\n" + "".join("      " + ln for ln in traceback.format_exc().splitlines(True)[-6:]))\n    print(f"\\nТестов пройдено: {ok} из {len(TESTS)}")\n    sys.stdout.flush()\n    sys.stderr.flush()\n    os._exit(0 if ok == len(TESTS) else 1)\n\n\nif __name__ == "__main__":\n    main()\n'}
TOUCHED = ["phone/server.py", "phone/install.py", ".github/workflows/tests.yml"]


def p(rel):
    return os.path.join(ROOT, *rel.split("/"))


def restore(backup):
    for rel in TOUCHED:
        b = os.path.join(backup, *rel.split("/"))
        if os.path.exists(b):
            shutil.copy2(b, p(rel))
    for rel in NEW:
        if os.path.exists(p(rel)):
            os.remove(p(rel))
    shutil.rmtree(p("cloud/space"), ignore_errors=True)
    print(f"Вернул прежние файлы из {backup}.")


if "--rollback" in sys.argv:
    cands = sorted(d for d in os.listdir(ROOT) if d.startswith("backup_cloudbrain_"))
    if not cands:
        sys.exit("Резервной копии нет.")
    restore(p(cands[-1]))
    sys.exit(0)
if not os.path.exists(p("core/cloud_sync.py")):
    sys.exit("Сначала поставь apply_cloud_memory.py (этап 1).")
if not os.path.exists(p("phone/server.py")):
    sys.exit("Сначала поставь apply_phone.py.")
if os.path.exists(p("cloud/atlas_cloud.py")):
    sys.exit("Уже установлено. Проверка: python tests/test_cloud_brain.py")

changed, status = {}, []
for rel, what, old, repl in PATCHES:
    s = changed.get(rel) or open(p(rel), encoding="utf-8").read()
    if s.count(old) == 1:
        changed[rel] = s.replace(old, repl, 1)
        status.append((what, "ok"))
    else:
        changed[rel] = s
        status.append((what, f"НЕ НАЙДЕНО ({s.count(old)})"))
for what, st in status:
    print(f"  {'✓' if st == 'ok' else '!'} {what}" + ("" if st == "ok" else f" — {st}"))
if any(st != "ok" for _, st in status):
    sys.exit("Код выглядит иначе, чем я ожидал — ничего не изменено. Пришли вывод.")

backup = p(time.strftime("backup_cloudbrain_%Y%m%d_%H%M%S"))
os.makedirs(backup, exist_ok=True)
for rel in TOUCHED:
    if os.path.exists(p(rel)):
        os.makedirs(os.path.dirname(os.path.join(backup, *rel.split("/"))), exist_ok=True)
        shutil.copy2(p(rel), os.path.join(backup, *rel.split("/")))
print(f"Резервная копия: {backup}")
for rel, s in list(changed.items()) + list(NEW.items()):
    os.makedirs(os.path.dirname(p(rel)), exist_ok=True)
    with open(p(rel), "w", encoding="utf-8", newline="\n") as f:
        f.write(s)
print(f"  ✓ папка cloud/ ({len([r for r in NEW if r.startswith('cloud/')])} файлов), keepalive, tests/test_cloud_brain.py")

suites = [f for f in sorted(os.listdir(p("tests"))) if f.startswith("test_") and f.endswith(".py")]
wf = ("name: tests\n\non:\n  push:\n  pull_request:\n\njobs:\n  atlas:\n    runs-on: ubuntu-latest\n    steps:\n"
      "      - uses: actions/checkout@v4\n      - uses: actions/setup-python@v5\n        with:\n          python-version: \"3.12\"\n"
      "      - run: pip install numpy pillow\n" + "".join(f"      - run: python tests/{s}\n" for s in suites))
os.makedirs(os.path.dirname(p(".github/workflows/tests.yml")), exist_ok=True)
with open(p(".github/workflows/tests.yml"), "w", encoding="utf-8", newline="\n") as f:
    f.write(wf)
print(f"  ✓ автопроверка на GitHub: {len(suites)} наборов тестов")

env = dict(os.environ, PYTHONIOENCODING="utf-8", PYTHONUTF8="1")
for suite in suites:
    r = subprocess.run([sys.executable, p("tests/" + suite)], cwd=ROOT, capture_output=True, text=True, encoding="utf-8",
                       errors="replace", timeout=300, env=env)
    m = re.search(r"Тестов пройдено: (\d+) из (\d+)", r.stdout + r.stderr)
    good = r.returncode == 0 and m and m.group(1) == m.group(2)
    print(f"  {'✓' if good else '✗'} tests/{suite}: {m.group(0) if m else 'итоговой строки нет'}")
    if not good:
        out = (r.stdout + "\n" + r.stderr).splitlines()
        for i, ln in enumerate(out):
            if ln.strip().startswith("✗"):
                print("      " + "\n      ".join(x.rstrip() for x in out[i:i + 7]))
        with open(p("cloudbrain_test_output.txt"), "w", encoding="utf-8") as f:
            f.write(r.stdout + "\n" + r.stderr)
        restore(backup)
        sys.exit("✗ Проверка не прошла — всё возвращено.")
print("\nГотово. Дальше: git push, затем настройка Space на Hugging Face (инструкция в чате).")
